const fs=require("fs");
const limit=29919;
const pin=JSON.parse(fs.readFileSync("payload/PIN","utf8"));
const isText=p=>/^\.agents\/skills\/joycraft-[^/]+\/SKILL\.md$/.test(p)||/^\.claude\/agents\/[^/]+\.md$/.test(p)||/^\.joycraft\/references\/.+\.md$/.test(p);
const count=t=>t.split(/\s+/).filter(Boolean).length;
const files=Object.keys(pin.files).filter(isText).sort();
let own=0; for(const f of files){ const n=count(fs.readFileSync("payload/"+f,"utf8")); own+=n; console.log(String(n).padStart(6)+"  payload/"+f); }
console.log("own count over the vendored payload ("+files.length+" skills, agent files and references): "+own+" words; limit "+limit);
import("../prototype-canonical-entry-file/tests/payload-bundle.mjs").then(m=>{
  const viaPayload=m.payloadWords(m.treeBundle("payload"));
  const viaProto=m.payloadWords(m.treeBundle());
  console.log("payloadWords(treeBundle(\"payload\")) with the helper of the prototype: "+viaPayload);
  console.log("payloadWords of the prototype checkout tree: "+viaProto);
  for(const tag of ["field-24","field-25","field-26"]) console.log("payloadWords at prototype tag "+tag+": "+(m.hasRevision(tag)?m.payloadWords(m.revisionBundle(tag)):"tag not available"));
  const ok=own<=limit&&viaPayload===own&&viaProto===own;
  console.log(ok?"RESULT: "+own+" <= "+limit+", and the three counts agree":"RESULT: not as expected"); process.exit(ok?0:1);
});

const cp=require("child_process");
const r=cp.spawnSync("node",["--test"],{cwd:"../prototype-canonical-entry-file",encoding:"utf8",env:{...process.env,CI:"1"},maxBuffer:256*1024*1024});
console.log("node --test in ../prototype-canonical-entry-file: exit code "+r.status+(r.signal?" signal "+r.signal:""));
const out=(r.stdout||"")+(r.stderr||"");
const lines=out.split("\n");
const failing=lines.filter(l=>/^\s*(✖|not ok)/.test(l));
console.log("failing test lines: "+failing.length); for(const l of failing) console.log(l);
console.log(lines.filter(l=>/^ℹ /.test(l)).join("\n"));
console.log("---- full output ----"); console.log(out);
process.exit(r.status===0?0:1);
